import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const colors = {
    background: new THREE.Color('#0b0b10'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38')
  };

  const timelines = [];

  // Base icosahedron geometry for all particles
  const icosaGeometry = new THREE.IcosahedronGeometry(0.012, 0);

  // Field particles (outer ellipsoidal shell)
  const fieldCount = 1110;
  const fieldPositions = [];
  const fieldPhases = new Float32Array(fieldCount);

  for (let i = 0; i < fieldCount; i++) {
    const u = Math.random();
    const v = Math.random();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);

    const x = Math.sin(phi) * Math.cos(theta) * 3;
    const y = Math.sin(phi) * Math.sin(theta) * 2;
    const z = Math.cos(phi) * 2.5 - 1.5;

    fieldPositions.push([x, y, z]);
    fieldPhases[i] = Math.random() * Math.PI * 2;
  }

  const fieldMaterial = new THREE.MeshStandardMaterial({
    color: colors.paper,
    metalness: 0,
    roughness: 1,
    emissive: new THREE.Color(0),
    emissiveIntensity: 0.9,
    transparent: true,
    opacity: 0.9
  });

  const fieldMesh = new THREE.InstancedMesh(icosaGeometry, fieldMaterial, fieldCount);
  const fieldMatrix = new THREE.Matrix4();
  const fieldMatrices = [];

  for (let i = 0; i < fieldCount; i++) {
    fieldMatrices[i] = new THREE.Matrix4();
    fieldMatrix.setPosition(...fieldPositions[i]);
    fieldMesh.setMatrixAt(i, fieldMatrix);
  }
  fieldMesh.instanceMatrix.needsUpdate = true;
  group.add(fieldMesh);

  // Core particles (inner accent sphere)
  const coreCount = 90;
  const corePositions = [];

  for (let i = 0; i < coreCount; i++) {
    const u = Math.random();
    const v = Math.random();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);

    const x = Math.sin(phi) * Math.cos(theta) * 0.25;
    const y = Math.sin(phi) * Math.sin(theta) * 0.25;
    const z = Math.cos(phi) * 0.25;

    corePositions.push([x, y, z]);
  }

  const coreMaterial = new THREE.MeshStandardMaterial({
    color: colors.accent,
    metalness: 0,
    roughness: 1,
    emissive: colors.accent,
    emissiveIntensity: 1.8,
    transparent: true,
    opacity: 0.95
  });
  coreMaterial.blending = THREE.AdditiveBlending;

  const coreMesh = new THREE.InstancedMesh(icosaGeometry, coreMaterial, coreCount);
  const coreMatrix = new THREE.Matrix4();

  for (let i = 0; i < coreCount; i++) {
    coreMatrix.setPosition(...corePositions[i]);
    coreMesh.setMatrixAt(i, coreMatrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  group.add(coreMesh);

  // Fog for depth falloff
  group.fog = new THREE.Fog(colors.background, 10, 4);

  // MSDF text rendering
  const heroText = ctx.fontAtlas.createText({
    text: 'NOVA ATELIER',
    fontFamily: 'Lora',
    fontSize: 0.62,
    fontWeight: '600',
    color: colors.paper,
    align: 'center'
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText({
    text: 'Precision instruments for the dark hours.',
    fontFamily: 'JetBrains Mono',
    fontSize: 0.2,
    fontWeight: '400',
    color: colors.paper,
    align: 'center'
  });
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText({
    text: 'EST. 2019 / GENEVA AND KYOTO',
    fontFamily: 'JetBrains Mono',
    fontSize: 0.09,
    fontWeight: '400',
    color: colors.paper,
    align: 'center'
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // Apply particle-emerge cinematic primitive
  ctx.primitives['particle-emerge'](group, {
    count: 1200,
    durationMs: 1400
  });

  // Ambient drift animation: orbit each particle ±0.04 units at 0.05 Hz (20s cycle)
  const driftTimeline = gsap.timeline({ repeat: -1 });
  driftTimeline.to({}, {
    duration: 20,
    onUpdate() {
      const elapsed = driftTimeline.time();

      for (let i = 0; i < fieldCount; i++) {
        const phase = fieldPhases[i];
        const angle = (elapsed * Math.PI * 0.1 * 2) + phase;

        const offsetX = Math.cos(angle) * 0.04;
        const offsetY = Math.sin(angle) * 0.04;

        fieldMatrices[i].setPosition(
          fieldPositions[i][0] + offsetX,
          fieldPositions[i][1] + offsetY,
          fieldPositions[i][2]
        );
        fieldMesh.setMatrixAt(i, fieldMatrices[i]);
      }
      fieldMesh.instanceMatrix.needsUpdate = true;
    }
  });
  timelines.push(driftTimeline);

  // Core pulse animation: emissive intensity sine 1.5 → 1.8 at 0.1 Hz (10s cycle)
  const pulseTimeline = gsap.timeline({ repeat: -1 });
  pulseTimeline.to(coreMaterial, {
    emissiveIntensity: 1.8,
    duration: 5,
    ease: 'sine.inOut'
  }, 0).to(coreMaterial, {
    emissiveIntensity: 1.5,
    duration: 5,
    ease: 'sine.inOut'
  }, 5);
  timelines.push(pulseTimeline);

  // Setup handlers
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = function() {
    timelines.forEach(tl => tl.kill());

    icosaGeometry.dispose();
    fieldMaterial.dispose();
    coreMaterial.dispose();

    if (heroText.geometry) heroText.geometry.dispose();
    if (heroText.material) heroText.material.dispose();
    if (subheadText.geometry) subheadText.geometry.dispose();
    if (subheadText.material) subheadText.material.dispose();
    if (captionText.geometry) captionText.geometry.dispose();
    if (captionText.material) captionText.material.dispose();
  };

  return group;
}
